using System.Text.Json;
using NanoQL.Bind.Emitting;
using static NanoQL.Bind.Tests.ExcelSurfaces;

namespace NanoQL.Bind.Tests;

/// <summary>
/// The builds (XLR5, XLD29, XLD36): every function of each shipped build generated byte for byte in its tests' build, the
/// fold's families and their keys, the stable build's families, the checked-in surface current, and the C outputs
/// unchanged with the Excel back end on.
/// </summary>
public class ExcelBuildTests
{
    /// <summary>Every function of each listed build is generated byte for byte as its tests' build generates it, its method's serial aside (XLD36).</summary>
    [Fact]
    public void EachListedFunctionIsTheTestsBuilds()
    {
        foreach ((ExcelOutput listed, ExcelOutput whole) in new[] { (ListedExperimental, WholeExperimental), (ListedStable, WholeStable) })
        {
            Assert.Equal(listed.Selection.Units.Count, Functions(listed).Count);
            Assert.Empty(Differences(listed, whole));
        }
    }

    /// <summary>
    /// A listed family keeps its constructions whole (round 1's F1-2): where the check withholds one, the family's text
    /// differs from its tests' build's, and the difference names the family and what the construction lacks, a gap for the
    /// list to close; on a scratch list without IntervalPrice, as the seed stood before the ruling of 2026-11-02.
    /// </summary>
    [Fact]
    public void APartlyWithheldFamilyNamesWhatItLacks()
    {
        ExcelOutput x = Run(true, new() { ["nql"] = NanoqlWith([], ["NanoQL.IntervalPrice"]) });
        Assert.Contains(Differences(x, WholeExperimental), d => d.StartsWith("nqlTimeSeries", StringComparison.Ordinal)
            && d.Contains("a family partly withheld", StringComparison.Ordinal) && d.Contains("lacks NanoQL.TimeSeries`1[[NanoQL.IntervalPrice", StringComparison.Ordinal));
    }

    /// <summary>
    /// The fold (XLD29): a generic type's constructions in one function per family key; a member whose parameter kinds differ
    /// by construction a family of its own; the stable build's family its stable constructions, the experimental one
    /// marked and refused (XLP62).
    /// </summary>
    [Fact]
    public void TheFoldsFamilies()
    {
        var m = Manifest(WholeExperimental);
        JsonElement size = m["nqlTimeSeriesSize"];
        Assert.Equal("type", size.GetProperty("args")[0].GetProperty("kind").GetString());
        Assert.Contains(size.GetProperty("constructions").EnumerateArray(), c => c.GetProperty("args").GetString() == "Double");
        Assert.Contains("|get|get_Size|handle", size.GetProperty("key").GetString(), StringComparison.Ordinal);
        Assert.True(m.Keys.Count(k => k.StartsWith("nqlTimeSeries", StringComparison.Ordinal) && k.Length > "nqlTimeSeries".Length && char.IsDigit(k[^1])) > 0);

        var stable = Manifest(WholeStable);
        var cubes = stable.Where(kv => kv.Key.StartsWith("nqlXabrSwaptionVolatilityCube", StringComparison.Ordinal)).ToList();
        Assert.Equal(9, cubes.Count);
        foreach ((string name, JsonElement f) in cubes)
        {
            var constructions = f.GetProperty("constructions").EnumerateArray().ToList();
            Assert.Contains(constructions, c => c.GetProperty("experimental").GetBoolean());
            Assert.False(f.GetProperty("experimental").GetBoolean());
            string c = f.GetProperty("c").GetString()!;
            Assert.DoesNotContain(constructions, x => x.GetProperty("c").GetString() == c && x.GetProperty("experimental").GetBoolean());
            Assert.Contains("is in the experimental build (nanoql-experimental64.xll)", Function(WholeStable, name), StringComparison.Ordinal);
        }
    }

    /// <summary>A construction added to a released family keeps the family's released name (XLD29): frozen by its key.</summary>
    [Fact]
    public void AFamilyKeepsItsReleasedName()
    {
        string key = Manifest(WholeExperimental)["nqlTimeSeriesSize"].GetProperty("key").GetString()!;
        string shipped = Path.Combine(Path.GetTempPath(), "nanoql-excel-family-" + Guid.NewGuid().ToString("N") + ".json");
        File.WriteAllText(shipped, $"{{\"functions\": [{{\"excel\": \"nqlTimeSeriesCount\", \"key\": {JsonSerializer.Serialize(key)}}}]}}");
        try
        {
            ExcelOutput x = Run(true, Whole(), shipped: shipped);
            Assert.Contains("nqlTimeSeriesCount", Manifest(x).Keys);
            Assert.DoesNotContain("nqlTimeSeriesSize", Manifest(x).Keys);
        }
        finally
        {
            File.Delete(shipped);
        }
    }

    /// <summary>The checked-in surface is the listed experimental build's (X1), the add-in's own and the withheld in it.</summary>
    [Fact]
    public void TheCheckedInSurfaceIsCurrent()
    {
        string path = Path.Combine(Surfaces.Repository, "bindings", "excel", "functions.json");
        Assert.Equal(File.ReadAllText(path), ListedExperimental.Manifest);
        using JsonDocument doc = JsonDocument.Parse(ListedExperimental.Manifest);
        Assert.Equal(["nqlxlError", "nqlxlRecipe", "nqlxlVersion", "nqlxlDrawsValues", "nqlxlDrawsWeights", "nqlxlDrawsNext"], doc.RootElement.GetProperty("own").EnumerateArray().Select(e => e.GetString()));
        Assert.Equal(19, doc.RootElement.GetProperty("withheld").GetArrayLength());
    }

    // Each listed function whose text differs from its tests' build's: a family partly withheld named with its
    // constructions' lacks, a gap for the list to close.
    private static List<string> Differences(ExcelOutput listed, ExcelOutput whole)
    {
        var tests = Functions(whole);
        var gaps = listed.Selection.Withheld.GroupBy(w => w.Name).ToDictionary(g => g.Key, g => string.Join("; ", g.Select(w => $"{w.Function.CName} lacks {string.Join(", ", w.Lacks)}")));
        return [.. Functions(listed).Where(kv => !(tests.TryGetValue(kv.Key, out string? t) && t == kv.Value))
            .Select(kv => gaps.TryGetValue(kv.Key, out string? gap) ? $"{kv.Key}: a family partly withheld ({gap}): list the type it lacks (XLD36)" : kv.Key)];
    }

    /// <summary>With the Excel back end on, the checked-in C outputs are unchanged: surface.json byte for byte (B1, XLD11's "where").</summary>
    [Fact]
    public void TheCOutputsAreUnchanged()
    {
        var inputs = new List<Reading.AssemblyInput>
        {
            new("nql", Path.Combine(AppContext.BaseDirectory, "NanoQL.dll")),
            new("nql", Path.Combine(AppContext.BaseDirectory, "NanoQL.Extensions.dll")),
        };
        Generation g = Generation.Run(inputs, [Path.Combine(Surfaces.Repository, "bindings", "roles.json")], null, ExcelOptions.Nanoql(true));
        Assert.Equal(File.ReadAllText(Path.Combine(Surfaces.Repository, "bindings", "surface.json")), g.Files["surface.json"]);
        Assert.Equal(Surfaces.Nanoql.Files["c/include/nanoql.h"], g.Files["c/include/nanoql.h"]);
    }
}
